#!/usr/bin/env python3
"""Test script to verify template refactoring works correctly."""

import tempfile
import json
from pathlib import Path
from claude_code_log.converter import convert_jsonl_to_html

def test_template_refactor():
    """Test that the template refactoring produces valid HTML."""

    # Create a temporary JSONL file with test data
    test_data = [
        {
            "type": "user",
            "timestamp": "2025-06-14T10:00:00Z",
            "message": {
                "role": "user",
                "content": [
                    {
                        "type": "text",
                        "text": "Hello, Claude! This is a test message."
                    }
                ]
            }
        },
        {
            "type": "assistant",
            "timestamp": "2025-06-14T10:00:30Z",
            "message": {
                "id": "msg_123",
                "role": "assistant",
                "content": [
                    {
                        "type": "text",
                        "text": "Hello! I can see you're testing the template refactoring."
                    }
                ]
            }
        }
    ]

    with tempfile.TemporaryDirectory() as temp_dir:
        temp_path = Path(temp_dir)
        jsonl_file = temp_path / "test.jsonl"

        # Write test data to JSONL file
        with open(jsonl_file, 'w') as f:
            for entry in test_data:
                f.write(json.dumps(entry) + '\n')

        # Convert to HTML
        html_file = convert_jsonl_to_html(jsonl_file)

        # Read and verify the HTML output
        html_content = html_file.read_text()

        # Basic checks to ensure HTML is generated correctly
        assert "<!DOCTYPE html>" in html_content
        assert "<title>Claude Transcript - test</title>" in html_content
        assert "Hello, Claude! This is a test message." in html_content
        assert "Hello! I can see you're testing the template refactoring." in html_content
        assert "class='message user'" in html_content
        assert "class='message assistant'" in html_content

        print("✓ Template refactoring test passed!")
        print(f"✓ Generated HTML file: {html_file}")
        print(f"✓ HTML content length: {len(html_content)} characters")

        return True

if __name__ == "__main__":
    test_template_refactor()

